// ----- SECURITY -----
function security(){
 const controls=[['Encryption everywhere','TLS 1.2+ in transit and encryption at rest. The website enforces HTTPS with HSTS and a strict set of security headers (CSP, anti-clickjacking, MIME-sniffing protection).'],['Strong access control','Least-privilege access, multi-factor authentication on every critical account, SSH keys over passwords, and secrets kept in a dedicated credential vault, never in code or chat.'],['Backups &amp; recovery','Encrypted, off-host backups of critical systems with restores tested regularly, so data and services can be recovered quickly.'],['Secure development','Version-controlled code with secret scanning, reviewed and tested changes, dependency checks, and least-privilege service accounts.'],['Client-system discipline','On your platform we use your credentials, honor your security policies, take only the access the work requires, and return or rotate it when the engagement ends.'],['Incident response','A documented plan with severity levels, defined breach-notification timelines, and an evidence-preservation runbook, so a bad day is handled, not improvised.']];
 const body=`<section class="page-intro" data-facet-src aria-labelledby="h1">${quiet}<p class="eyebrow">Trust &amp; Security</p><h1 id="h1">Your data, handled <span class="shine">with care.</span></h1><p class="lede">Omar Huertas LLC is built and run by a CISSP-certified ServiceNow architect. Security and privacy aren&rsquo;t an afterthought: they&rsquo;re how we work, on our own systems and on yours.</p></section>
<section aria-labelledby="sc-h"><div class="section-head"><div><p class="eyebrow">Security controls</p><h2 id="sc-h">How we protect information</h2></div></div><dl class="ruled">${controls.map(([t,d])=>`<div><dt>${t}</dt><dd>${d}</dd></div>`).join('')}</dl></section>
<section aria-labelledby="pv-h"><div class="section-head"><div><p class="eyebrow">Privacy &amp; data protection</p><h2 id="pv-h">What we collect, and what we don&rsquo;t</h2></div></div><ul class="grid3 glass-list">
<li class="glass"><h3>Data minimization</h3><p>We collect only what&rsquo;s needed. Website forms capture just your name, email, and message; our apps are built privacy-first with minimal data.</p></li>
<li class="glass"><h3>Payments stay with the processor</h3><p>Card payments are handled by Stripe&rsquo;s hosted checkout. Raw card data never touches our systems (PCI&nbsp;DSS&nbsp;SAQ&nbsp;A scope).</p></li>
<li class="glass"><h3>Your privacy rights</h3><p>We don&rsquo;t sell or share your personal information. You can request access, correction, or deletion of your data anytime: email <a href="mailto:${EMAIL}?subject=Data%20Request">${EMAIL}</a>.</p></li>
<li class="glass"><h3>Children&rsquo;s apps</h3><p>Our kids&rsquo; education apps are data-minimal: no behavioral advertising, no third-party tracking, and parental consent before any personal data is collected (COPPA-aligned).</p></li>
<li class="glass"><h3>Cookies &amp; tracking</h3><p>This website uses only essential, first-party cookies needed for it to function. We don&rsquo;t use advertising cookies or cross-site tracking, so there&rsquo;s no consent wall to click through.</p></li></ul>
<p class="note"><a href="/privacy-policy.html">Read the full Privacy Policy</a>, the <a href="/terms.html">Terms</a>, <a href="/legal.html">Legal notices</a> and the <a href="/accessibility.html">Accessibility statement</a>.</p></section>
<section aria-labelledby="cp-h"><div class="section-head"><div><p class="eyebrow">Compliance posture</p><h2 id="cp-h">Standards we hold ourselves to</h2></div></div><div class="table-panel glass"><table><thead><tr><th scope="col">Area</th><th scope="col">Status</th></tr></thead><tbody>
<tr><th scope="row">Web security (HTTPS, HSTS, CSP, security headers)</th><td>In place</td></tr><tr><th scope="row">Accessibility, WCAG 2.1 AA</th><td>Conformant (verified)</td></tr><tr><th scope="row">Privacy, CCPA/CPRA &amp; GDPR principles</th><td>Aligned</td></tr><tr><th scope="row">Payments, PCI DSS (SAQ A via Stripe)</th><td>In scope &amp; maintained</td></tr><tr><th scope="row">Children&rsquo;s privacy, COPPA (kids&rsquo; apps)</th><td>Aligned</td></tr><tr><th scope="row">SOC 2 / ISO 27001 / NIST 800-171</th><td class="wrap-cell">Control foundation in place; formal attestation available on request for qualifying engagements</td></tr></tbody></table></div>
<p class="note">SOC 2, ISO 27001, and CMMC are verified by independent assessors. We maintain the underlying controls and policy documentation and pursue formal attestation as client engagements require. HIPAA-regulated work is supported only under a signed Business Associate Agreement.</p></section>
<section aria-labelledby="rd-h"><div class="section-head"><div><p class="eyebrow">Responsible disclosure</p><h2 id="rd-h">Found a security issue?</h2></div></div><p class="prose-p">We welcome responsible disclosure. If you believe you&rsquo;ve found a vulnerability in our website or apps, please email <a href="mailto:${EMAIL}?subject=Security%20Disclosure">${EMAIL}</a> with the details and steps to reproduce. Please give us a reasonable chance to investigate and remediate before any public disclosure. We&rsquo;re grateful for the help, and we&rsquo;ll keep you updated.</p><div class="actions">${button(`mailto:${EMAIL}?subject=Security%20Disclosure`,'Report a security issue')}<a class="text-link" href="/.well-known/security.txt">security.txt</a></div></section>`;
 return page({path:'/security.html',title:'Trust & Security | Omar Huertas LLC',description:'How Omar Huertas LLC protects data: security controls, privacy, and compliance posture for clients and partners.',body});
}

// ----- 404 -----
function notFound(){
 const body=`<section class="page-intro err" data-facet-src aria-labelledby="h1">${quiet}<p class="err-code" aria-hidden="true">404</p><p class="eyebrow">Page not found</p><h1 id="h1">That page could not be found.</h1><p class="lede">The page may have moved or the address may be incorrect. Try the menu, press <kbd>⌘</kbd><kbd>K</kbd> to jump anywhere, or start over at home.</p><div class="actions">${button('/','Return home')}<a class="text-link" href="/servicenow-lexicon/">Open the ServiceNow Lexicon</a></div></section>`;
 return page({path:'/404.html',title:'Page Not Found | Omar Huertas LLC',description:'Page not found.',body});
}

// ----- DOCUMENT PAGES (legal, privacy, terms, accessibility) from the old flipbook content -----
const slug=s=>s.toLowerCase().replace(/&[a-z]+;/g,'').replace(/<[^>]+>/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function docPage({path,file,title,description,label}){
 return async()=>{
  const {pages}=await json(file);
  const cover=pages[0].html;
  const eyebrow=(cover.match(/c-eyebrow">([\s\S]*?)<\/div>/)||[])[1]||'';
  const h1=(cover.match(/<h1>([\s\S]*?)<\/h1>/)||[])[1]||title;
  const sub=(cover.match(/c-sub">([\s\S]*?)<\/p>/)||[])[1]||'';
  const updated=(cover.match(/cm-rel">([\s\S]*?)<\/div>/)||[])[1]||'';
  // the "Contents" page is navigation, regenerated below from the headings
  const bodyHtml=pages.slice(1).filter(p=>!/>Contents<\/h1>/.test(p.html)).map(p=>p.html).join('\n');
  let n=0;const toc=[];
  const withIds=bodyHtml.replace(/<h2>([\s\S]*?)<\/h2>/g,(m,t)=>{const id=slug(t)||'s'+(++n);toc.push([id,t]);return `<h2 id="${id}">${t}</h2>`});
  const body=`<section class="page-intro doc-intro" data-facet-src aria-labelledby="h1">${quiet}<p class="eyebrow">${eyebrow.replace(/&middot;/g,'&middot;')}</p><h1 id="h1">${h1.replace('class="accent"','class="shine"')}</h1><p class="lede">${sub}</p><p class="small doc-meta">Omar Huertas LLC. ${updated}.</p></section>
<div class="doc"><nav class="doc-toc" aria-label="Contents"><p class="eyebrow">Contents</p><ol>${toc.map(([id,t])=>`<li><a href="#${id}">${t}</a></li>`).join('')}</ol></nav><article class="paper prose">${withIds}</article></div>`;
  return page({path,title,description,wide:false,body,bodyClass:'doc-page'});
 };
}

// ----- THE LEXICON: a reference, not a flipbook -----
const GROUPS=[['Foundations',0,12],['CMDB &amp; ITOM',12,24],['ITSM',24,36],['ITAM &amp; Source-to-Pay',36,48],['HR, customer &amp; field service',48,61],['Security, risk &amp; compliance',61,73],['Building on the platform',73,80],['AI &amp; analytics',80,85],['Business &amp; career',85,96],['Glossary',96,98]];
async function lexicon(){
 const {pages}=await json('servicenow-lexicon');
 const cover=pages[0],back=pages[pages.length-1],entries=pages.slice(1,-1);
 const sub=(cover.html.match(/c-sub'>([\s\S]*?)<\/p>/)||[])[1]||'';
 const rel=(cover.html.match(/cm-rel'>([\s\S]*?)<\/div>/)||[])[1]||'';
 const demote=h=>h.replace(/<h3>/g,'<h4>').replace(/<\/h3>/g,'</h4>').replace(/<h2>/g,'<h3>').replace(/<\/h2>/g,'</h3>').replace(/<h1>/g,'<h2>').replace(/<\/h1>/g,'</h2>').replace(/<span class='eyebrow'>/g,'<span class="eyebrow">');
 const used=new Set();const ids=entries.map(e=>{let id=slug(e.doc)||'p';let k=id,i=2;while(used.has(k))k=id+'-'+i++;used.add(k);return k});
 const titleOf=e=>((e.html.match(/<h1>([\s\S]*?)<\/h1>/)||[])[1]||e.doc).replace(/<[^>]+>/g,'');
 const groupOf=i=>GROUPS.find(([,a,b])=>i>=a&&i<b)?.[0]||'';
 const toc=GROUPS.map(([g,a,b])=>`<li><b>${g}</b><ol>${entries.slice(a,b).map((e,j)=>`<li><a href="#${ids[a+j]}">${titleOf(e)}</a></li>`).join('')}</ol></li>`).join('');
 const articles=entries.map((e,i)=>{const g=groupOf(i);const gi=GROUPS.findIndex(x=>x[0]===g);const first=GROUPS[gi]&&GROUPS[gi][1]===i;const inner=demote(e.html).replace(/<h2>[\s\S]*?<\/h2>/,'');return `${first?`<h2 class="lex-group" id="g-${slug(g)}">${g}</h2>`:''}<details class="lex" id="${ids[i]}" data-k="${esc((e.doc+' '+e.html.replace(/<[^>]+>/g,' ')).toLowerCase().replace(/\s+/g,' ').slice(0,900))}"${i===0?' open':''}><summary><span class="lex-doc">${e.doc}</span><span class="lex-title">${titleOf(e)}</span><span class="lex-n">${i+1}</span></summary><div class="paper lex-paper">${inner}</div></details>`}).join('\n');
 const backHtml=back.html.replace("<a class='bc-cta'>Work with us &rarr;</a>",`<p>${button('/contact.html','Work with us')}</p>`).replace(/<h2>/,'<h2 id="end">');
 const body=`<section class="lex-hero" data-facet-src aria-labelledby="h1">${field}<div class="wrap lex-hero-in"><div><p class="eyebrow">The field guide. ServiceNow, explained</p><h1 id="h1">The ServiceNow <span class="shine">Lexicon</span></h1><p class="lede">${sub}</p><p class="small doc-meta">An educational guide by Omar Huertas LLC. ${rel}.</p></div>
<form class="lex-search" role="search" data-lexicon-search><label for="lex-q">Find a term</label><input id="lex-q" type="search" placeholder="CMDB, CSDM, MID Server, Now Assist…" autocomplete="off"><p class="small" data-lexicon-count>${entries.length} chapters. Type to filter; press <kbd>/</kbd> to jump here.</p></form></div></section>
<div class="wrap lex-layout"><nav class="lex-toc" aria-label="Chapters"><p class="eyebrow">Chapters</p><ol class="lex-groups">${toc}</ol></nav><div class="lex-body">${articles}<p class="lex-empty" hidden>No chapter matches. Try a shorter word, like &ldquo;asset&rdquo; or &ldquo;flow&rdquo;.</p><section class="paper lex-back" aria-labelledby="end">${backHtml}</section></div></div>`;
 LEX_PAL=entries.map((e,i)=>['/servicenow-lexicon/#'+ids[i],titleOf(e),'lexicon']);
 return page({path:'/servicenow-lexicon/index.html',wide:true,script:'lexicon',title:'The ServiceNow Lexicon | Omar Huertas LLC',description:'What ServiceNow is, what it does, every acronym and module decoded, and why your company needs it. In plain English. A free guide by Omar Huertas LLC.',body,bodyClass:'doc-page'});
}

// ----- write everything -----
const LEX=await lexicon();
const out=[['index.html',home],['about.html',about],['services.html',services],['industries.html',industries],['support.html',support],['contact.html',contact],['security.html',security],['404.html',notFound],
 ['legal.html',docPage({path:'/legal.html',file:'legal',title:'Legal Notices & Disclaimers | Omar Huertas LLC',description:'Trademarks, affiliations, disclaimers, intellectual property, and liability terms for Omar Huertas LLC and the Services we provide.'})],
 ['privacy-policy.html',docPage({path:'/privacy-policy.html',file:'privacy-policy',title:'Privacy Policy | Omar Huertas LLC',description:'How Omar Huertas LLC collects, uses, shares, and protects information across our website, our consulting and implementation services, and the applications we develop and publish.'})],
 ['terms.html',docPage({path:'/terms.html',file:'terms',title:'Terms & Conditions | Omar Huertas LLC',description:'The terms that govern your use of the Omar Huertas LLC website, our consulting and implementation services, and our applications.'})],
 ['accessibility.html',docPage({path:'/accessibility.html',file:'accessibility',title:'Accessibility | Omar Huertas LLC',description:'Our accessibility commitment: WCAG 2.1 AA, keyboard support, captions, and a built-in accessibility toolbar.'})],
 ['servicenow-lexicon/index.html',()=>LEX]];
await mkdir(join(ROOT,'servicenow-lexicon'),{recursive:true});
for(const [f,fn] of out){const html=await fn();if(/\bElite\b/.test(html))throw new Error(f+': "Elite" must not appear');await writeFile(join(ROOT,f),html);console.log('wrote',f,(html.length/1024).toFixed(0)+'KB')}
